<?php
require __DIR__.'/server/bootstrap.php';$user=require_user();require __DIR__.'/server/commerce.php';require __DIR__.'/server/catalog.php';ensure_commerce();
$q=db()->prepare('SELECT * FROM dwa_orders WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$o=$q->fetch();
