?><p><strong>Nomor: <?=e($o['order_no'])?></strong><br>Tanggal checkout: <?=e($o['created_at'])?><br>Verifikasi pembayaran: <?=e($o['verified_at'])?><br>Status: <?=e(order_status($o['status']))?></p><h2>Data pemesan & pengiriman dokumen</h2><p><?=e($c['recipient'])?><br>WhatsApp: <?=e($c['phone'])?><br><?=e($c['address'].', '.$c['village'].', '.$c['district'].', '.$c['city'].', '.$c['province'].' '.$c['postal'])?></p><table><thead><tr><th>Layanan / kelengkapan</th><th>Jumlah</th><th>Harga satuan</th><th>Subtotal</th></tr></thead><tbody><?php foreach(json_decode($o['items_json'],true) as $i): ?><tr><td><strong><?=e($i['name'])?></strong><?php if($i['includes']): ?><p><?=e(implode(', ',$i['includes']))?></p><?php endif ?><?php if($i['bonuses']): ?><p>Bonus: <?=e(implode(', ',$i['bonuses']))?></p><?php endif ?></td><td><?=(int)$i['qty']?></td><td><?=rupiah($i['price'])?></td><td><?=rupiah($i['price']*$i['qty'])?></td></tr><?php endforeach ?></tbody></table><p>Subtotal layanan: <?=rupiah((int)$o['subtotal'])?><br>Ongkir: <?=rupiah((int)$o['shipping'])?><br><strong>Total terverifikasi: <?=rupiah((int)$o['subtotal']+(int)$o['shipping'])?></strong></p><p>Metode pembayaran: <?=e($o['payment_method'])?><br>Referensi bukti pembayaran: <?=e($o['payment_reference'])?><br>Pembayaran diverifikasi manual oleh admin DWA.</p><p>Catatan pemesan: <?=e($c['note']?:'—')?></p><hr><p>PT Drajat Wiguna Adidaya · DWA Bussines<br>Bank BRI 4355-0104-0248530 · A/N PT DRAJAT WIGUNA ADIDAYA</p><small>Dokumen ini adalah ringkasan pesanan terverifikasi, bukan faktur pajak. Buka di browser dan pilih Cetak → Simpan sebagai PDF untuk menyimpan versi PDF.</small></body></html>
